const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
let darioWins = 0;

for (let i = 0; i < n; i++) {
  const d = data[1 + 2 * i];
  const x = data[2 + 2 * i];
  const diff = (d - x + 5) % 5;
  if (diff === 1 || diff === 2) darioWins++;
}

console.log(darioWins > n / 2 ? 'dario' : 'xerxes');
